package app.vidloader;import android.content.Context;import java.io.*;import java.nio.file.*;import java.net.URI;
public class MediaExport{static URI copy(Context c,DownloadStore.Task t,boolean ignored)throws IOException{File from=DownloadStore.get(c).file(t),folder=new File(c.getSharedPreferences("settings",0).getString("destination",System.getProperty("user.home")+"/Downloads/Snagfox"));folder.mkdirs();String name=DownloadStore.safeName(t.name);File target=new File(folder,name);int n=2;while(target.exists()){int dot=name.lastIndexOf('.');String base=dot>0?name.substring(0,dot):name,ext=dot>0?name.substring(dot):"";target=new File(folder,base+" ("+(n++)+")"+ext);}Files.copy(from.toPath(),target.toPath());return target.toURI();}}